import React, { useState, useEffect } from 'react';

const Dashboard = () => {
  const [offset, setOffset] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e) => {
    const { innerWidth, innerHeight } = window;
    // حركة خفيفة للصورة بناءً على الماوس
    const x = (e.clientX / innerWidth - 0.5) * 20;
    const y = (e.clientY / innerHeight - 0.5) * 20;
    setOffset({ x, y });
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // دوال للتعامل مع الأزرار
  const handlePropertiesClick = () => {
    document.querySelector('button[title="العقارات"]')?.click();
  };

  const handleContactClick = () => {
    const fab = document.querySelector('.contact-fab');
    if (fab) fab.click();
  };

  const handleLoginClick = () => {
    const btn = document.querySelector('#client-login-button');
    if (btn) btn.click();
  };

  return (
    <div className="container-fluid p-0 overflow-hidden position-relative" style={{ minHeight: '100vh' }}>
      
      {/* Background Image with Parallax */}
      <div 
        style={{
          position: 'absolute',
          top: -20,
          left: -20,
          right: -20,
          bottom: -20,
          backgroundImage: 'url(https://images.unsplash.com/photo-1600596542815-27bfef402399?ixlib=rb-4.0.3&auto=format&fit=crop&w=1920&q=80)',
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          transform: `translate(${offset.x}px, ${offset.y}px) scale(1.05)`,
          transition: 'transform 0.1s ease-out',
          zIndex: 0
        }}
      ></div>

      {/* Dark Overlay */}
      <div className="position-absolute top-0 start-0 w-100 h-100 bg-dark" style={{ opacity: 0.6, zIndex: 1 }}></div>

      <div className="row g-0 align-items-center position-relative h-100" style={{ minHeight: '100vh', zIndex: 2 }}>
        
        {/* Text Content */}
        <div className="col-lg-8 mx-auto text-center p-5 fade-in">
          <div className="p-lg-5">
            <h1 className="display-3 fw-bold mb-4 text-white" style={{ textShadow: '0 2px 15px rgba(0,0,0,0.5)' }}>
              مستقبل العقارات <br/> بين يديك
            </h1>
            <p className="lead text-light mb-5 mx-auto" style={{ lineHeight: '1.8', maxWidth: '700px', textShadow: '0 1px 5px rgba(0,0,0,0.5)' }}>
              منصة <strong>سمسار برو</strong> هي الحل الأمثل لإدارة وتسويق العقارات بذكاء. 
              نجمع بين التكنولوجيا الحديثة وسهولة الاستخدام لنوفر لك تجربة فريدة.
            </p>
            
            <div className="d-flex gap-3 flex-wrap justify-content-center">
              <button className="btn btn-primary btn-lg px-5 rounded-pill shadow-lg" onClick={handlePropertiesClick}>
                تصفح العقارات
              </button>
              <button className="btn btn-outline-light btn-lg px-5 rounded-pill backdrop-blur" onClick={handleContactClick}>
                تواصل معنا
              </button>
              <button className="btn btn-success btn-lg px-5 rounded-pill shadow-lg" onClick={handleLoginClick}>
                سجل دخولك الآن
              </button>
            </div>

            <div className="mt-5 pt-4 border-top border-light border-opacity-25 w-75 mx-auto">
              <div className="row text-center">
                <div className="col">
                  <h3 className="fw-bold text-warning">+500</h3>
                  <small className="text-white-50">عقار متاح</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-warning">+100</h3>
                  <small className="text-white-50">عميل سعيد</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-warning">24/7</h3>
                  <small className="text-white-50">دعم فني</small>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <style>{`
        .backdrop-blur {
            backdrop-filter: blur(5px);
            -webkit-backdrop-filter: blur(5px);
        }
      `}</style>
    </div>
  );
};

export default Dashboard;
